<script setup lang="ts">
import {onMounted,ref} from 'vue';import {adminUsers} from '../lib/admin';type Staff={id:string;username:string;email:string|null;phone:string|null;role:string;disabled:boolean;created_at:string};const users=ref<Staff[]>([]),error=ref(''),busy=ref(false),show=ref(false),edit=ref<Staff|null>(null),username=ref(''),email=ref(''),phone=ref(''),password=ref(''),role=ref('cashier'),caps=ref(''),pages=ref('{}');async function load(){try{const r=await adminUsers<{users:Staff[]}>('list');users.value=r.users}catch(e:any){error.value=e.message}}async function create(){busy.value=true;error.value='';try{await adminUsers('create',{username:username.value,email:email.value,phone:phone.value||null,password:password.value,role:role.value});show.value=false;username.value='';email.value='';phone.value='';password.value='';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}async function toggle(u:Staff){try{await adminUsers('set_disabled',{user_id:u.id,disabled:!u.disabled});await load()}catch(e:any){error.value=e.message}}async function updateRole(u:Staff,event:Event){try{await adminUsers('set_role',{user_id:u.id,role:(event.target as HTMLSelectElement).value});await load()}catch(e:any){error.value=e.message}}async function openAccess(u:Staff){edit.value=u;try{const r=await adminUsers<{caps:string[];pages:Record<string,boolean>}>('get_access',{user_id:u.id});caps.value=r.caps.join(', ');pages.value=JSON.stringify(r.pages,null,2)}catch(e:any){error.value=e.message}}async function saveAccess(){if(!edit.value)return;try{const parsed=JSON.parse(pages.value||'{}');await adminUsers('set_access',{user_id:edit.value.id,caps:caps.value.split(',').map(x=>x.trim()).filter(Boolean),pages:parsed});edit.value=null;await load()}catch(e:any){error.value='Check the page access JSON: '+e.message}}async function resetPassword(u:Staff){const value=prompt('Enter a temporary password of at least 10 characters for '+u.username);if(!value)return;try{await adminUsers('reset_password',{user_id:u.id,password:value});alert('Password reset successfully. Share it securely with the staff member.')}catch(e:any){error.value=e.message}}onMounted(load);
</script>
<template><section><div class="flex flex-wrap justify-between items-end gap-4"><div><p class="text-sm text-indigo-600 font-semibold">ADMINISTRATION</p><h1 class="text-3xl font-bold mt-2">Users & access</h1><p class="text-slate-500 text-sm mt-1">Create staff accounts, assign roles and control individual permissions.</p></div><button class="btn btn-primary" @click="show=true">＋ Add user</button></div><p v-if="error" class="text-sm text-red-600 mt-4">{{error}}</p><div class="panel overflow-x-auto mt-6"><table class="table w-full"><thead><tr><th>Username</th><th>Contact</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td class="font-semibold">{{u.username}}</td><td>{{u.email||'—'}}<br>{{u.phone||''}}</td><td><select class="field min-w-28" :value="u.role" @change="updateRole(u,$event)"><option value="admin">Admin</option><option value="manager">Manager</option><option value="cashier">Cashier</option></select></td><td><span :class="u.disabled?'text-red-600':'text-green-700'">{{u.disabled?'Disabled':'Active'}}</span></td><td><div class="flex flex-wrap gap-3"><button class="text-indigo-700" @click="openAccess(u)">Access</button><button class="text-indigo-700" @click="resetPassword(u)">Reset password</button><button class="text-slate-600" @click="toggle(u)">{{u.disabled?'Enable':'Disable'}}</button></div></td></tr><tr v-if="!users.length"><td colspan="5" class="text-center text-slate-500">No staff accounts found.</td></tr></tbody></table></div><div v-if="show" class="modal-mask"><form class="modal-card space-y-4" @submit.prevent="create"><h2 class="text-xl font-bold">Create staff account</h2><label class="block text-sm">Username<input v-model="username" class="field mt-1" minlength="3" required></label><label class="block text-sm">Email address<input v-model="email" type="email" class="field mt-1" required></label><label class="block text-sm">Phone<input v-model="phone" class="field mt-1"></label><label class="block text-sm">Temporary password<input v-model="password" type="password" class="field mt-1" minlength="10" required></label><label class="block text-sm">Role<select v-model="role" class="field mt-1"><option value="cashier">Cashier</option><option value="manager">Manager</option><option value="admin">Admin</option></select></label><div class="flex justify-end gap-2"><button type="button" class="btn btn-muted" @click="show=false">Cancel</button><button class="btn btn-primary" :disabled="busy">{{busy?'Creating…':'Create account'}}</button></div></form></div><div v-if="edit" class="modal-mask"><form class="modal-card space-y-4" @submit.prevent="saveAccess"><h2 class="text-xl font-bold">Access settings — {{edit.username}}</h2><label class="block text-sm">Capabilities (comma-separated)<textarea v-model="caps" class="field mt-1" rows="3" placeholder="view_costs, manage_inventory"></textarea></label><label class="block text-sm">Page access overrides (JSON)<textarea v-model="pages" class="field mt-1 font-mono text-xs" rows="8"></textarea></label><p class="text-xs text-slate-500">Set a page to true to allow or false to deny. Omitted pages use role defaults.</p><div class="flex justify-end gap-2"><button type="button" class="btn btn-muted" @click="edit=null">Cancel</button><button class="btn btn-primary">Save access</button></div></form></div></section></template>
